#!/usr/bin/env bun

/**
 * Accepted Changes - between-release ledger for the LifeOS upstream repo
 *
 * Generated by the maintainer, read by every install. The Upgrade skill tracks
 * this repo releases-first (#1868), so between releases it sees nothing, while
 * fixes are accepted by closing an issue with a comment naming the change and
 * where it landed. That record is public but scattered one comment per thread.
 *
 * This writes it to a single tracked file. The intended use is one line at the
 * end of a triage pass:
 *
 *   bun AcceptedChanges.ts && git add ACCEPTED_CHANGES.* && git commit -m "triage: ledger"
 *
 * Every install then reads one file instead of crawling the tracker.
 *
 * Appends and is safe to re-run. Two properties make that true rather than
 * merely likely, and both are easy to get wrong:
 *
 *   - The stored watermark advances ONLY after a complete pass. A run truncated
 *     by --limit, or cut short by a rate limit, records its rows and leaves the
 *     watermark where it was, so the remainder is still reachable next time.
 *   - The query re-asks from the day BEFORE the watermark, because GitHub's
 *     `closed:>DATE` excludes the whole named day and `closed:>=` does not
 *     exist. Merge-by-issue-number absorbs the overlap.
 *
 * Paths are published as the comment wrote them, minus the `LifeOS/install/`
 * payload prefix. They are NOT normalised to a single root, because the
 * comments are not written against one: measured over 312 rows, 90 of 210 path
 * mentions resolve directly under the payload root and another 79 only resolve
 * one level deeper (a comment saying `PULSE/manage.ps1` means
 * `LIFEOS/PULSE/manage.ps1`). A consumer should resolve by suffix match rather
 * than by prefix. The 40 that resolve nowhere are themselves signal: a row
 * naming a file the published payload does not contain is a change that has not
 * shipped, which is the condition this ledger exists to surface.
 *
 * A path carrying someone's absolute location is dropped rather than rewritten:
 * the ledger is a public file and must not advertise the maintainer's filesystem.
 *
 * Usage:
 *   bun AcceptedChanges.ts                      # append since the watermark
 *   bun AcceptedChanges.ts --rebuild            # regenerate from the latest release
 *   bun AcceptedChanges.ts --since 2026-08-14   # from a date
 *   bun AcceptedChanges.ts --limit 25           # sample; never advances the watermark
 *   bun AcceptedChanges.ts --repo owner/name    # another repo
 *   bun AcceptedChanges.ts --out DIR            # output directory
 *
 * Auth:
 *   Enumeration uses /search/issues (10 requests/minute unauthenticated, a
 *   separate budget from the 60/hour core limit), then one core request per
 *   issue for its comments. A first full run wants GITHUB_TOKEN; incremental
 *   runs do not.
 *
 * Output (tracked content, committed — not per-install state):
 *   ACCEPTED_CHANGES.md    - table plus each resolution verbatim, newest first
 *   ACCEPTED_CHANGES.json  - { generated, repo, release, watermark, complete, entries[] }
 */

import { writeFileSync, readFileSync, mkdirSync, existsSync } from 'fs';
import { join, resolve, dirname } from 'path';

interface Entry {
  issue: number;
  url: string;
  title: string;
  reporter: string;
  closed_at: string;
  /** GitHub's closure reason: `completed`, `not_planned`, or null. */
  state_reason: string | null;
  /** The maintainer's closing comment, verbatim. */
  resolution: string | null;
  /** Install-relative paths named in the closing comment. */
  paths: string[];
  /** A release the comment points at, when it names one affirmatively. */
  release_hint: string | null;
  /** Whether the issue body carried a Suggested fix section or a diff. */
  public_fix: boolean;
}

interface Ledger {
  generated: string;
  repo: string;
  release: string | null;
  /** Everything closed on or before this date is recorded. Advances only after a complete pass. */
  watermark: string | null;
  /** False when the last run was truncated or cut short, so the watermark is behind the rows. */
  complete: boolean;
  entries: Entry[];
}

interface Options {
  repo: string;
  since: string | null;
  limit: number;
  jsonOnly: boolean;
  rebuild: boolean;
  out: string | null;
}

const API = 'https://api.github.com';
const DEFAULT_REPO = 'danielmiessler/LifeOS';

/**
 * The ledger is tracked content, so it belongs at the top of the working repo,
 * not beside the tool: this file ships inside `LifeOS/install/`, which lands in
 * a user's config root at an unknown depth (`INSTALL.md` is explicit that the
 * root is not always `~/.claude`), so counting `..` levels cannot be right in
 * both places. Resolve the enclosing git repo, and fail loudly instead of
 * writing somewhere arbitrary.
 */
function findRepoRoot(start: string): string | null {
  let dir = start;
  for (let i = 0; i < 12; i += 1) {
    if (existsSync(join(dir, '.git'))) return dir;
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
  return null;
}

function parseArgs(argv: string[]): Options {
  const opts: Options = { repo: DEFAULT_REPO, since: null, limit: Infinity, jsonOnly: false, rebuild: false, out: null };
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--repo') opts.repo = argv[++i] ?? '';
    else if (a === '--since') opts.since = argv[++i] ?? '';
    else if (a === '--limit') {
      const raw = argv[++i];
      const n = Number(raw);
      if (!Number.isInteger(n) || n < 1) throw new Error(`--limit must be a positive integer, got "${raw}"`);
      opts.limit = n;
    } else if (a === '--out') opts.out = argv[++i] ?? '';
    else if (a === '--json') opts.jsonOnly = true;
    else if (a === '--rebuild') opts.rebuild = true;
    else if (a === '--help' || a === '-h') {
      console.log('bun AcceptedChanges.ts [--repo owner/name] [--since YYYY-MM-DD] [--limit N] [--out DIR] [--json] [--rebuild]');
      process.exit(0);
    } else throw new Error(`unknown argument "${a}"`);
  }
  if (!/^[\w.-]+\/[\w.-]+$/.test(opts.repo)) throw new Error(`--repo must be owner/name, got "${opts.repo}"`);
  if (opts.since && !/^\d{4}-\d{2}-\d{2}$/.test(opts.since)) throw new Error(`--since must be YYYY-MM-DD, got "${opts.since}"`);
  if (!opts.out) {
    const root = findRepoRoot(import.meta.dir);
    if (!root) throw new Error('no enclosing git repository found, so there is nowhere obvious to write the ledger. Pass --out explicitly.');
    opts.out = root;
  }
  return opts;
}

function headers(): Record<string, string> {
  const h: Record<string, string> = { Accept: 'application/vnd.github+json', 'User-Agent': 'LifeOS-Upgrade-AcceptedChanges' };
  // Token travels in the header, never in the URL.
  const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
  if (token) h.Authorization = `Bearer ${token}`;
  return h;
}

class RateLimited extends Error {}

async function api<T>(path: string): Promise<T> {
  const res = await fetch(path.startsWith('http') ? path : `${API}${path}`, { headers: headers() });
  if (res.status === 403 || res.status === 429) {
    const reset = res.headers.get('x-ratelimit-reset');
    const when = reset ? new Date(Number(reset) * 1000).toISOString() : 'unknown';
    throw new RateLimited(
      `GitHub rate limit (remaining=${res.headers.get('x-ratelimit-remaining')}, resets ${when}). ` +
        `Search allows 10/minute and core 60/hour unauthenticated. Set GITHUB_TOKEN, or pass --limit to sample.`,
    );
  }
  if (!res.ok) throw new Error(`GitHub ${res.status} ${res.statusText} for ${path}`);
  return (await res.json()) as T;
}

async function latestRelease(repo: string): Promise<{ tag: string; published: string } | null> {
  try {
    const r = await api<{ tag_name: string; published_at: string }>(`/repos/${repo}/releases/latest`);
    return { tag: r.tag_name, published: r.published_at };
  } catch {
    return null;
  }
}

/** The day before `date`, because `closed:>DATE` excludes DATE and `closed:>=` is unavailable. */
export function dayBefore(date: string): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

interface RawIssue {
  number: number;
  title: string;
  user: string;
  closed_at: string;
  state_reason: string | null;
  html_url: string;
  body: string;
}

/**
 * Order is NOT relied on. GitHub's issue search has no `closed` sort field, and
 * measured against the live API an invalid sort is silently ignored rather than
 * rejected: `sort=closed`, `sort=created` and `sort=bogusfield` all return the
 * same ordering. So a truncated result is an arbitrary subset of the window,
 * which is exactly why the watermark may only advance after a complete pass.
 *
 * `skip` carries the issue numbers already recorded, so a --limit run spends
 * its budget on rows the ledger does not have and successive runs walk the
 * backlog instead of re-reading the same page.
 */
async function closedIssues(repo: string, since: string, limit: number, skip: Set<number>): Promise<{ issues: RawIssue[]; truncated: boolean }> {
  const out: RawIssue[] = [];
  const perPage = 100;
  let truncated = false;
  for (let page = 1; page <= 10; page += 1) {
    const q = encodeURIComponent(`repo:${repo} is:issue is:closed closed:>${since}`);
    const r = await api<{ total_count: number; items: any[] }>(
      `/search/issues?q=${q}&per_page=${perPage}&page=${page}`,
    );
    if (!r.items?.length) break;
    for (const i of r.items) {
      if (skip.has(i.number)) continue;
      if (out.length >= limit) {
        truncated = true;
        break;
      }
      out.push({
        number: i.number,
        title: i.title,
        user: i.user?.login ?? 'unknown',
        closed_at: i.closed_at,
        state_reason: i.state_reason ?? null,
        html_url: i.html_url,
        body: i.body ?? '',
      });
    }
    if (truncated || r.items.length < perPage) break;
  }
  return { issues: out, truncated };
}

/**
 * A repo-relative path mentioned in prose. Conservative by design: the column
 * it feeds is published, so a false positive asserts that a change landed
 * somewhere it did not.
 *
 * `(?<![\w./-])` is what makes the URL case work. Without it a match simply
 * begins after `https://` and any guard downstream never sees a scheme.
 */
const PATH_RE = /(?<![\w./\\-])((?:[\w.-]+\/)+[\w.-]+\.\w{2,5}(?::\d+)?|[\w.-]+\.(?:ts|tsx|js|mjs|md|json|ps1|sh|yml|yaml)(?::\d+)?)(?![\w/\\-])/g;
const URL_RE = /\b[a-z][a-z0-9+.-]*:\/\/\S+|\bwww\.\S+/gi;
/** Prose words that match the path shape and are never a file in this repo. */
const PROSE_FALSE_POSITIVES = new Set(['node.js', 'next.js', 'nuxt.js', 'vue.js', 'express.js', 'react.js', 'd3.js']);
/** A path carrying an absolute location is dropped, never rewritten. */
const ABSOLUTE_MARKERS = /^(?:\/|[a-z]:[\\/])|(?:^|\/)(?:home|users|mnt|var|tmp|opt|etc|private)\//i;
/** The payload prefix in the repo; installs see these paths without it. */
const PAYLOAD_PREFIX = /^LifeOS\/install\//;

export function extractPaths(text: string): string[] {
  const cleaned = text.replace(URL_RE, ' ');
  const seen = new Set<string>();
  for (const m of cleaned.matchAll(PATH_RE)) {
    let p = m[1];
    if (PROSE_FALSE_POSITIVES.has(p.toLowerCase())) continue;
    if (ABSOLUTE_MARKERS.test(p)) continue;
    p = p.replace(PAYLOAD_PREFIX, '');
    if (p) seen.add(p);
  }
  return [...seen];
}

/**
 * Release pointers are read per sentence rather than by one big pattern: the
 * maintainer writes "Next release carries it", "This goes out in the next
 * public release (8.3.0)" and "You'll see it in the release that's about to
 * ship", and a single word-order-sensitive regex misses most of them.
 */
const RELEASE_TOKEN = /\brelease(?:d|s)?\b/i;
const VERSION_RE = /\b(\d+\.\d+\.\d+)\b/;
/** "will not be in the next release" must not read as a release pointer. */
const NEGATION_RE = /\b(?:not|never|won'?t|will\s+not|isn'?t|is\s+not|no\s+longer|deferred|postponed|instead\s+of)\b/i;

export function extractRelease(text: string): string | null {
  for (const sentence of text.split(/(?<=[.!?;\n])\s+/)) {
    if (!RELEASE_TOKEN.test(sentence)) continue;
    if (NEGATION_RE.test(sentence)) continue;
    const v = sentence.match(VERSION_RE);
    return v ? v[1] : 'next release';
  }
  return null;
}

/** The closing comment: the last comment written by a maintainer, across all pages. */
async function resolutionFor(repo: string, issue: number, owner: string): Promise<string | null> {
  type Comment = { user: { login: string }; body: string; author_association: string };
  const all: Comment[] = [];
  for (let page = 1; page <= 10; page += 1) {
    const batch = await api<Comment[]>(`/repos/${repo}/issues/${issue}/comments?per_page=100&page=${page}`);
    all.push(...batch);
    if (batch.length < 100) break;
  }
  const maintainer = all.filter(
    (c) => c.user?.login === owner || ['OWNER', 'MEMBER', 'COLLABORATOR'].includes(c.author_association),
  );
  return maintainer[maintainer.length - 1]?.body?.trim() || null;
}

/** A pipe in a cell would split the row; titles and logins are not trusted to be clean. */
const cell = (s: string) => s.replace(/\|/g, '\\|');

function toMarkdown(l: Ledger): string {
  const out: string[] = [];
  out.push('# Accepted changes');
  out.push('');
  out.push(`Fixes accepted in \`${l.repo}\` and described in the closing comment, generated from those`);
  out.push('comments by `skills/Upgrade/Tools/AcceptedChanges.ts`. Nothing here is hand-maintained.');
  out.push('');
  out.push(`- Repo: \`${l.repo}\``);
  out.push(`- Latest release at generation: \`${l.release ?? 'unknown'}\``);
  out.push(`- Recorded through: \`${l.watermark ?? 'n/a'}\`${l.complete ? '' : ' (last pass incomplete — rows exist past the watermark)'}`);
  out.push(`- Entries: ${l.entries.length}`);
  out.push('');
  out.push('A row means the issue was closed and a maintainer described the resolution. It does not');
  out.push('mean the change is installable, which is the distinction this file exists to make visible.');
  out.push('Paths are install-relative and extracted from the comment text, so a row with no path is a');
  out.push('comment that named none.');
  out.push('');
  out.push('| Issue | Closed | Reason | Reporter | Where it landed | Release | Public fix |');
  out.push('|---|---|---|---|---|---|---|');
  for (const e of l.entries) {
    const paths = e.paths.length ? e.paths.map((p) => `\`${cell(p)}\``).join('<br>') : '—';
    out.push(
      `| [#${e.issue}](${e.url}) | ${e.closed_at.slice(0, 10)} | ${cell(e.state_reason ?? '—')} | ${cell(e.reporter)} | ${paths} | ${cell(e.release_hint ?? '—')} | ${e.public_fix ? 'yes' : 'no'} |`,
    );
  }
  out.push('');
  out.push('## Resolutions');
  out.push('');
  for (const e of l.entries) {
    out.push(`### #${e.issue} — ${e.title}`);
    out.push('');
    out.push(e.resolution ? `> ${e.resolution.replace(/\n+/g, '\n> ')}` : '_No maintainer comment on the thread._');
    out.push('');
  }
  // Generation timestamp lives at the END on purpose: the Upgrade skill's
  // changelog fetcher hashes the first 3KB to decide whether a source changed,
  // so a timestamp near the top would report a change on every regeneration.
  out.push('---');
  out.push('');
  out.push(`_Generated ${l.generated}._`);
  return out.join('\n');
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const [owner] = opts.repo.split('/');
  const outDir = opts.out as string;
  const jsonPath = join(outDir, 'ACCEPTED_CHANGES.json');

  let prior: Ledger | null = null;
  if (!opts.rebuild && existsSync(jsonPath)) {
    try {
      prior = JSON.parse(readFileSync(jsonPath, 'utf-8')) as Ledger;
    } catch (err) {
      throw new Error(`${jsonPath} exists but could not be parsed (${(err as Error).message}). Fix it or pass --rebuild.`);
    }
  }
  const existing = Array.isArray(prior?.entries) ? prior!.entries : [];

  const release = await latestRelease(opts.repo);
  const watermark = opts.rebuild ? null : prior?.watermark ?? null;
  const base = opts.since ?? watermark ?? release?.published?.slice(0, 10);
  if (!base) throw new Error(`No --since given and ${opts.repo} has no published release to default to.`);
  // Resuming re-asks the watermark day, because `closed:>DATE` excludes DATE and
  // the watermark day is already partly recorded; merge-by-issue absorbs it.
  // A first pass does NOT: `closed:>` the release date correctly excludes
  // closures made on release day, which shipped with that release.
  const queryFrom = watermark && !opts.since ? dayBefore(watermark) : base;
  if (watermark && !opts.since) console.error(`resuming from watermark ${watermark} (querying closed:>${queryFrom})`);

  if (!process.env.GITHUB_TOKEN && !process.env.GH_TOKEN) {
    console.error('warning: no GITHUB_TOKEN. Search allows 10/minute and core 60/hour unauthenticated,');
    console.error('         and one core request is spent per issue. A first full run wants a token.');
  }

  const recorded = new Set(existing.map((e) => e.issue));
  const { issues, truncated } = await closedIssues(opts.repo, queryFrom, opts.limit, opts.limit === Infinity ? new Set() : recorded);
  console.error(`found ${issues.length} closed issue(s) in ${opts.repo} with closed:>${queryFrom}${truncated ? ` (truncated at --limit ${opts.limit})` : ''}`);

  const fresh: Entry[] = [];
  let cutShort = false;
  for (const i of issues) {
    let resolution: string | null = null;
    try {
      resolution = await resolutionFor(opts.repo, i.number, owner);
    } catch (err) {
      // Keep what was gathered, but the watermark must not move past rows we never read.
      console.error(`stopped at #${i.number}: ${(err as Error).message}`);
      cutShort = true;
      break;
    }
    fresh.push({
      issue: i.number,
      url: i.html_url,
      title: i.title,
      reporter: i.user,
      closed_at: i.closed_at,
      state_reason: i.state_reason,
      resolution,
      paths: resolution ? extractPaths(resolution) : [],
      release_hint: resolution ? extractRelease(resolution) : null,
      public_fix: /##\s*Suggested fix/i.test(i.body) || /```diff/.test(i.body),
    });
  }

  const byIssue = new Map<number, Entry>();
  for (const e of existing) byIssue.set(e.issue, e);
  let added = 0;
  for (const e of fresh) {
    if (!byIssue.has(e.issue)) added += 1;
    byIssue.set(e.issue, e);
  }
  const merged = [...byIssue.values()].sort((a, b) => b.closed_at.localeCompare(a.closed_at));

  // The watermark advances only when this pass saw everything it asked for.
  const complete = !truncated && !cutShort;
  const newest = merged[0]?.closed_at?.slice(0, 10) ?? null;
  const ledger: Ledger = {
    generated: new Date().toISOString(),
    repo: opts.repo,
    release: release?.tag ?? null,
    watermark: complete ? newest : prior?.watermark ?? null,
    complete,
    entries: merged,
  };
  if (!complete) {
    console.error(`watermark held at ${ledger.watermark ?? 'n/a'} because the pass was incomplete; re-run to reach the rest`);
  }

  if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });
  writeFileSync(jsonPath, JSON.stringify(ledger, null, 2));
  console.error(`wrote ${jsonPath}`);
  if (!opts.jsonOnly) {
    const mdPath = join(outDir, 'ACCEPTED_CHANGES.md');
    writeFileSync(mdPath, toMarkdown(ledger));
    console.error(`wrote ${mdPath}`);
  }

  const withPaths = merged.filter((e) => e.paths.length).length;
  console.error(`${merged.length} entries (${added} new, ${merged.length - added} kept), ${withPaths} naming at least one path`);
}

// Guarded so the extractors above can be imported by a test without running a pass.
if (import.meta.main) {
  main().catch((err) => {
    console.error(`AcceptedChanges failed: ${err.message}`);
    process.exit(1);
  });
}
